import { type SynapseEnhancedHttpClient } from "../utils/http.ts";
import { MatrixClientApi } from "../constants/api.ts";
import type { IPresenceApi, IPresenceStatus, ISetPresence, IStatusResponse } from "../models/types.ts";
import { handleApiResponse } from "../utils/response-formatter.ts";
import { BaseApi } from "../utils/base-api.ts";

export class PresenceApi extends BaseApi implements IPresenceApi {
    public constructor(httpClient: SynapseEnhancedHttpClient) {
        super(httpClient);
    }

    public async getStatus(userId: string): Promise<IPresenceStatus> {
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                presence?: IPresenceStatus;
            };
            error?: string;
        }>(`${MatrixClientApi.PRESENCE}/status`, { user_id: userId });

        const data = handleApiResponse(response, "Failed to get presence status");

        return (
            data.presence || {
                user_id: userId,
                presence: "offline",
                last_active_ago: 0,
            }
        );
    }

    public async setStatus(params: ISetPresence): Promise<IStatusResponse> {
        const response = await this.httpClient.post<{
            status: string;
            error?: string;
        }>(`${MatrixClientApi.PRESENCE}/status`, params as unknown as Record<string, unknown>);

        handleApiResponse(response, "Failed to set presence status");

        return { status: "ok" };
    }

    public async getPresence(userId: string): Promise<IPresenceStatus> {
        return this.getStatus(userId);
    }

    public async updatePresence(userId: string, presence: string, statusMsg?: string): Promise<void> {
        await this.setStatus({
            user_id: userId,
            status: presence,
            status_msg: statusMsg,
        });
    }
}
